#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
using namespace std;

int N, L, E;
vector<vector<int>> adj;
vector<bool> isGateway;

// 從 agent 位置 BFS，找出「通往最近 gateway 的最後一條連結」
pair<int, int> findLinkToCut(int start)
{
    vector<bool> visited(N, false);
    queue<int> q;
    q.push(start);
    visited[start] = true;

    while (!q.empty())
    {
        int u = q.front();
        q.pop();
        for (int v : adj[u])
        {
            if (isGateway[v]) return make_pair(u, v);   // 這一刀直接斷開 gateway
            if (!visited[v])
            {
                visited[v] = true;
                q.push(v);
            }
        }
    }
    return make_pair(-1, -1);
}

void cutLink(int a, int b)
{
    adj[a].erase(remove(adj[a].begin(), adj[a].end(), b), adj[a].end());
    adj[b].erase(remove(adj[b].begin(), adj[b].end(), a), adj[b].end());
}

int main()
{
    cin >> N >> L >> E;
    adj.assign(N, vector<int>());
    isGateway.assign(N, false);

    for (int i = 0; i < L; i++)
    {
        int a, b;
        cin >> a >> b;
        adj[a].push_back(b);
        adj[b].push_back(a);
    }

    for (int i = 0; i < E; i++)
    {
        int g;
        cin >> g;
        isGateway[g] = true;
    }

    while (true)
    {
        int SI;
        if (!(cin >> SI)) break;

        pair<int, int> link = findLinkToCut(SI);
        if (link.first == -1) break;

        cout << link.first << " " << link.second << endl;
        cutLink(link.first, link.second);
    }
    return 0;
}
